import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.BM5YPQmL.js";const g=JSON.parse('{"title":"Agent access","description":"","frontmatter":{},"headers":[],"relativePath":"agent-access.md","filePath":"agent-access.md","lastUpdated":1793717423000}'),d={name:"agent-access.md"};function i(n,e,c,r,l,h){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="agent-access" tabindex="-1">Agent access <a class="header-anchor" href="#agent-access" aria-label="Permalink to &quot;Agent access&quot;">​</a></h1><p>How an AI agent should read these docs. This page describes website plumbing only; it is not part of any protocol.</p><h2 id="what-is-served" tabindex="-1">What is served <a class="header-anchor" href="#what-is-served" aria-label="Permalink to &quot;What is served&quot;">​</a></h2><p>Everything below is relative to the docs root, <code>/docs/</code> by default. On the GitHub Pages deployment the root is <code>https://kernlize.github.io/docs/</code>.</p><table tabindex="0"><thead><tr><th>Want</th><th>Fetch</th></tr></thead><tbody><tr><td>An index of every docs page, grouped like the sidebar, with one-line descriptions</td><td><code>/docs/llms.txt</code> (<a href="https://llmstxt.org/" target="_blank" rel="noreferrer">llmstxt.org</a> format)</td></tr><tr><td>Every docs page in one file</td><td><code>/docs/llms-full.txt</code></td></tr><tr><td>One page as Markdown</td><td>The page path with <code>.md</code>: <code>/docs/index.md</code>, <code>/docs/concepts/guard.md</code>, <code>/docs/packages/index.md</code></td></tr><tr><td>The generated API reference</td><td><code>/docs/api/index.html</code> and <code>/docs/api/modules/_kernl_&lt;package&gt;.html</code>; HTML only</td></tr><tr><td>The landing site&#39;s own index</td><td><code>/llms.txt</code> and <code>/llms-full.txt</code> at the site root, built by the Astro site</td></tr></tbody></table><h2 id="markdown-twins" tabindex="-1">Markdown twins <a class="header-anchor" href="#markdown-twins" aria-label="Permalink to &quot;Markdown twins&quot;">​</a></h2><p>Every HTML page on this docs site has a Markdown twin at a fixed path, generated at build time from the same source as the HTML:</p><ul><li>A page served at <code>/docs/concepts/guard</code> (or <code>/docs/concepts/guard.html</code>) has its twin at <code>/docs/concepts/guard.md</code>.</li><li>A directory page such as <code>/docs/packages/</code> has its twin at <code>/docs/packages/index.md</code>.</li><li>The docs root <code>/docs/</code> has its twin at <code>/docs/index.md</code>.</li></ul><p>Each HTML page names its twin in <code>&lt;head&gt;</code>:</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">link</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> rel</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;alternate&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;text/markdown&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> href</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/docs/concepts/guard.md&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p>In the twins, frontmatter is removed, <code>:::</code> containers become blockquotes with a bold label, and internal links are rewritten to absolute <code>.md</code> URLs so a twin can be read on its own. Links into the generated API reference keep their <code>.html</code> extension because TypeDoc output has no Markdown form.</p><h2 id="reading-order" tabindex="-1">Reading order <a class="header-anchor" href="#reading-order" aria-label="Permalink to &quot;Reading order&quot;">​</a></h2><ol><li>Fetch <code>/docs/llms.txt</code> and pick the section you need. The sections mirror the sidebar: Start, Concepts, Tutorials, How-tos, Packages, Reference, Policies.</li><li>For a question about behaviour, read the concept page first (for example <code>/docs/concepts/guard.md</code>), then the how-to.</li><li>For a question about an export, read the package page (<code>/docs/packages/&lt;name&gt;.md</code>) for the version, install line and export list, then the TypeDoc module page for signatures.</li><li>Treat <code>/docs/alpha-status.md</code> as authoritative about what is implemented. A contract described in a concept page may be an interface without a backend; the status page says which.</li></ol><h2 id="what-these-docs-are-not" tabindex="-1">What these docs are not <a class="header-anchor" href="#what-these-docs-are-not" aria-label="Permalink to &quot;What these docs are not&quot;">​</a></h2><p>They are not the protocol. NIP-5D is specified in <a href="https://github.com/nostr-protocol/nips/pull/2303" target="_blank" rel="noreferrer">nostr-protocol/nips PR #2303</a> and the NAP domains in <a href="https://github.com/napplet/naps" target="_blank" rel="noreferrer">napplet/naps</a>. Where a kernl page and the specification disagree, the specification wins and the page has a bug; see <a href="./policies/spec-conformance">Spec conformance</a>.</p><p>They are also not the public website. The landing site at <code>/</code> follows the <a href="./policies/public-vocabulary">public vocabulary</a> rule and never names a protocol. These pages name everything precisely because developers need the names.</p><h2 id="build-contract" tabindex="-1">Build contract <a class="header-anchor" href="#build-contract" aria-label="Permalink to &quot;Build contract&quot;">​</a></h2><p><code>llms.txt</code>, <code>llms-full.txt</code> and the twins are written by <code>docs/.vitepress/agent-output.ts</code> in VitePress&#39;s <code>buildEnd</code> hook. <code>scripts/audit-docs.mjs</code> fails the build when any of them is missing, so their presence is part of <code>pnpm docs:check</code>, not a convention.</p>',18)])])}const u=t(d,[["render",i]]);export{g as __pageData,u as default};
